from ta_moler.cmd.positioner_1d_krk.generic_positioner_krk import GenericPositionerKrk
from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number
import re

__author__ = 'Marcin Usielski'
__copyright__ = 'Copyright (C) 2022, Nokia'
__email__ = 'marcin.usielski@nokia.com'


class GetAngle(GenericPositionerKrk):
    """get_angle command."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        get_angle command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GetAngle, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                       runner=runner)
        self.ret_required = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "get_angle"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_angle(line=line)
            except ParsingDone:
                pass
        super(GetAngle, self).on_new_line(line=line, is_full_line=is_full_line)

    # Current angle of the positioner: 30.0
    _re_angle = re.compile(r"Current angle of the positioner:\s+(?P<VALUE>\-?\d+\.\d+|\-?\.\d+|\-?\d+)")

    def _parse_angle(self, line):
        if self._regex_helper.search_compiled(GetAngle._re_angle, line):
            self.current_ret['angle_raw'] = self._regex_helper.group("VALUE")
            self.current_ret['angle'] = convert_to_number(self._regex_helper.group("VALUE"))
            raise ParsingDone()


COMMAND_OUTPUT = """get_angle
Current angle of the positioner: 30.0
positioner (calibrated)>"""

COMMAND_RESULT = {
    'angle': float("30.0"),
    'angle_raw': '30.0'
}

